create policy edit_members on public.trip_days for all to authenticated using(public.can_edit(trip_id)) with check(public.can_edit(trip_id));
create trigger touch before update on public.trip_days for each row execute function public.touch_updated_at();
create index on public.trip_days(trip_id);
