create unique index one_visited_meal on public.meal_candidates(trip_id,meal_schedule_id) where visited and meal_schedule_id is not null;
create function public.validate_scope() returns trigger language plpgsql set search_path=public,pg_temp as $$
begin
 if new.schedule_item_id is not null and not exists(select 1 from schedule_items where id=new.schedule_item_id and trip_id=new.trip_id and (new.date is null or date=new.date)) then raise exception 'Schedule date mismatch'; end if;
 return new;
end $$;
create trigger packing_scope before insert or update on public.packing_items for each row execute function public.validate_scope();
create trigger checklist_scope before insert or update on public.checklist_items for each row execute function public.validate_scope();
create function public.validate_meal() returns trigger language plpgsql set search_path=public,pg_temp as $$ begin
 if new.meal_schedule_id is not null and not exists(select 1 from schedule_items where id=new.meal_schedule_id and trip_id=new.trip_id and type='MEAL') then raise exception 'Meal schedule required'; end if; return new; end $$;
create trigger meal_scope before insert or update on public.meal_candidates for each row execute function public.validate_meal();
-- Derived splits always follow the expense, including updates and deletes.
create function public.sync_splits() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin
 delete from expense_splits where expense_id=new.id;
 insert into expense_splits(trip_id,expense_id,user_id,amount_yen) select new.trip_id,new.id,user_id,case slot when 'USER_A' then new.share_a_yen else new.share_b_yen end from trip_members where trip_id=new.trip_id;
 return new; end $$;
alter table public.expense_splits drop constraint expense_splits_trip_id_expense_id_fkey;
alter table public.expense_splits add foreign key(trip_id,expense_id) references public.expenses(trip_id,id) on delete cascade;
create trigger expense_splits_sync after insert or update on public.expenses for each row execute function public.sync_splits();
drop policy edit_members on public.expense_splits;
revoke all on function public.sync_splits() from public;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('reservation-files','reservation-files',false,10485760,array['application/pdf','image/png','image/jpeg','image/webp']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy private_read on storage.objects for select to authenticated using(bucket_id='reservation-files' and exists(select 1 from public.trip_members where trip_id::text=(storage.foldername(name))[1] and user_id=auth.uid()));
create policy private_insert on storage.objects for insert to authenticated with check(bucket_id='reservation-files' and exists(select 1 from public.trip_members where trip_id::text=(storage.foldername(name))[1] and user_id=auth.uid() and role in ('OWNER','EDITOR')));
create policy private_delete on storage.objects for delete to authenticated using(bucket_id='reservation-files' and exists(select 1 from public.trip_members where trip_id::text=(storage.foldername(name))[1] and user_id=auth.uid() and role in ('OWNER','EDITOR')));
